{{#css: 


.pz-box {
	position: relative;
}

.pz-bg {
	position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    overflow: hidden;
    z-index: 1;
}

.pz-bg img {
    object-fit: cover;
}

.pz-table-box {
    z-index: 2;
    width: 100%;
    position: relative;
	padding: 10px;

}

.tran-table{
    width: 100%;
}

.pz-bg img {
    width: 100%;
    height: 100%;
}

.tran-table tbody,
.tran-table tbody tr {
	width: 100%;
}

.tran-table tbody th,
.tran-table tbody td {
	width: 10%;
	color: #fff;
	text-align: center;
}
.tran-table tbody th{
    height: 30px;
}
.tran-table tbody td{
    height: 100%;
    padding: 2px;
    font-size: 11px;
    vertical-align: top;
}
.tran-table tbody td img{
    max-height:78px;
    width: 78px;
}

.tran-table .zw-td-sca img{
    scale: 0.7;
    transform: translateY(-20%);
}
.tran-table .zw-td-sca span{
    transform: translateY(-20px);
}
.tran-table .zw-td-sca-right img{
    scale: 0.7;
    transform: translateY(-20%);
}
.tran-table .zw-td-sca-right span{
    transform: translateY(-20px);
}
.tran-table tbody td a:last-child,
.tran-table tbody td span{
    color: #fff;
    text-shadow: #000 0 0 4px;
}
}}
